    constructor(C _c) { c = _c; }

    function run(address caller, address other) public payable {
        require(caller != address(0));
        require(other != address(0));
        require(other != caller);

        uint beforeCaller = c.tokenBalance(caller);
        uint beforeOther = c.tokenBalance(other);
        uint beforeContractBalance = address(c).balance;

        bool reverted;
        try c.airDrop() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterCaller = c.tokenBalance(caller);
        uint afterOther = c.tokenBalance(other);
        uint afterContractBalance = address(c).balance;

        assert(
            reverted == (beforeCaller != 0) &&
            (reverted || afterCaller == beforeCaller + 20) &&
            (!reverted || afterCaller == beforeCaller) &&
            afterOther == beforeOther &&
            afterContractBalance == beforeContractBalance
        );
    }
}

